PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('schema','1'),('global_cap','4'),('project_cap','2'),('dispatch_enabled','false'),('mode','real');
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,aliases TEXT NOT NULL DEFAULT '[]',charter TEXT NOT NULL,repository TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'active',created INTEGER NOT NULL,completed INTEGER,completed_seq INTEGER);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,project TEXT REFERENCES projects(id),parent TEXT REFERENCES agents(id),role TEXT NOT NULL,harness TEXT NOT NULL DEFAULT 'none',model TEXT NOT NULL DEFAULT '',token_hash TEXT UNIQUE NOT NULL,depth INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'idle',created INTEGER NOT NULL,last_seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,requirements TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'ready',role TEXT NOT NULL DEFAULT 'engineer',priority INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL,updated INTEGER NOT NULL,completed INTEGER,completed_seq INTEGER,generation INTEGER NOT NULL DEFAULT 0,recoveries INTEGER NOT NULL DEFAULT 0,replans INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',next_check INTEGER,owner TEXT REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS requirements(task TEXT NOT NULL REFERENCES tasks(id),version INTEGER NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(task,version));
CREATE TABLE IF NOT EXISTS dependencies(task TEXT NOT NULL REFERENCES tasks(id),depends_on TEXT NOT NULL REFERENCES tasks(id),PRIMARY KEY(task,depends_on),CHECK(task!=depends_on));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),generation INTEGER NOT NULL,version INTEGER NOT NULL,agent TEXT NOT NULL REFERENCES agents(id),state TEXT NOT NULL,started INTEGER NOT NULL,heartbeat INTEGER NOT NULL,progress_at INTEGER NOT NULL,fingerprint TEXT NOT NULL DEFAULT '',repeats INTEGER NOT NULL DEFAULT 0,workspace TEXT NOT NULL DEFAULT '',runtime_id TEXT NOT NULL DEFAULT '',runtime_generation TEXT NOT NULL DEFAULT '',reserved_children INTEGER NOT NULL DEFAULT 0,UNIQUE(task,generation));
CREATE UNIQUE INDEX IF NOT EXISTS one_current_attempt ON attempts(task) WHERE state IN ('running','unknown','review','paused','recovering');
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),attempt TEXT NOT NULL REFERENCES attempts(id),version INTEGER NOT NULL,sha TEXT NOT NULL,body TEXT NOT NULL,code_revision TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,artifact TEXT NOT NULL REFERENCES artifacts(id),reviewer TEXT NOT NULL REFERENCES agents(id),passed INTEGER NOT NULL,evidence TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY,task TEXT REFERENCES tasks(id),kind TEXT NOT NULL,reason TEXT NOT NULL,owner TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',next_check INTEGER NOT NULL,created INTEGER NOT NULL,resolution TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS one_incident ON incidents(task,kind) WHERE state='open';
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,sender TEXT NOT NULL,recipient TEXT NOT NULL REFERENCES agents(id),task TEXT REFERENCES tasks(id),version INTEGER,generation INTEGER,thread TEXT NOT NULL,body TEXT NOT NULL,priority TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'persisted',created INTEGER NOT NULL,deadline INTEGER NOT NULL,read_at INTEGER,acted_at INTEGER);
CREATE INDEX IF NOT EXISTS inbox ON messages(recipient,created);
CREATE TABLE IF NOT EXISTS responses(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,project TEXT REFERENCES projects(id),task TEXT REFERENCES tasks(id),body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,entity TEXT NOT NULL,actor TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(actor TEXT NOT NULL,id TEXT NOT NULL,request_hash TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(actor,id));
CREATE TABLE IF NOT EXISTS capsules(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),generation INTEGER NOT NULL,version INTEGER NOT NULL,manifest TEXT NOT NULL,sha TEXT NOT NULL,verified_by TEXT REFERENCES agents(id),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge(id TEXT PRIMARY KEY,project TEXT REFERENCES projects(id),title TEXT NOT NULL,body TEXT NOT NULL,sources TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'candidate',supersedes TEXT REFERENCES knowledge(id),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,harness TEXT NOT NULL,model TEXT NOT NULL,version TEXT NOT NULL,capabilities TEXT NOT NULL,evidence TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS runtime_observations(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL,observed INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),attempt TEXT NOT NULL REFERENCES attempts(id),verb TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',receipt TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),profile TEXT NOT NULL,outcome TEXT NOT NULL,elapsed_ms INTEGER NOT NULL,cost REAL,created INTEGER NOT NULL);
